283	    /**
284	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
285	     * source of truth for how an email is persisted, so inputs that differ only in letter case
286	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
287	     * (create and update, mapper or hand-copied) stores the same canonical value.
288	     *
289	     * @param email the raw email, possibly {@code null}
290	     * @return the lower-cased form, or {@code null} if the input was {@code null}
291	     */
292	    public static String normalizeEmail(String email) {
293	        return email == null ? null : email.toLowerCase();
294	    }
295	
296	    /**
297	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
298	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
299	     */
300	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
301	        "mailinator.com",
302	        "tempmail.com",
303	        "guerrillamail.com");
304	
305	    /**
306	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
307	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
308	     * This is the single source of truth for which email domains are rejected, shared by any
309	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
310	     *
311	     * @param email the owner's email, possibly {@code null}
312	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
313	     */
314	    public static boolean isDisposableEmailDomain(String email) {
315	        if (email == null) {
316	            return false;
317	        }
318	        int at = email.lastIndexOf('@');
319	        if (at < 0) {
320	            return false;
321	        }
322	        String domain = email.substring(at + 1).toLowerCase();
323	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
324	    }
325	
326	    /**
327	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
328	     * truth for how a telephone is compared and persisted, so inputs that differ only in
329	     * formatting (spaces, dashes, brackets) are treated as the same number.
330	     *
331	     * <p>The rules are:
332	     * <ul>
333	     *   <li>spaces, dashes and brackets are stripped;</li>
334	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
335	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
336	     *       is dropped from the national digits;</li>
337	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
338	     *   <li>for a recognized country code the national number (the digits after the country
339	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
340	     *       digits and {@code '+1'} requires 10.</li>
341	     * </ul>
342	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
343	     * values are returned unchanged.
344	     *
345	     * @param telephone the raw telephone, possibly {@code null}
346	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
347	     *     valid E.164 number
348	     */
349	    public static String normalizeTelephone(String telephone) {
350	        if (telephone == null) {
351	            return null;
352	        }
353	        String trimmed = telephone.trim();
354	        boolean hasCountryCode = trimmed.startsWith("+");
355	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
356	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
357	        if (hasCountryCode) {
358	            stripped = stripped.substring(1);
359	        }
360	        if (!stripped.matches("\\d+")) {
361	            return null;
362	        }
363	        String digits;
364	        if (hasCountryCode) {
365	            digits = stripped;
366	        } else {
367	            if (stripped.startsWith("0")) {
368	                stripped = stripped.substring(1);
369	            }
370	            digits = "61" + stripped;
371	        }
372	        if (digits.length() < 8 || digits.length() > 15) {
373	            return null;
374	        }
375	        if (!hasValidNationalNumberLength(digits)) {
376	            return null;
377	        }
378	        return "+" + digits;
379	    }
380	
381	    /**
382	     * Format a stored E.164 telephone for human display: the country code, a space, then the
383	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
384	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
385	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
386	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
387	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
388	     * kept unchanged elsewhere.
389	     *
390	     * @param telephone the stored E.164 telephone, possibly {@code null}
391	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
392	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
393	     *     unchanged
394	     */
395	    public static String telephoneDisplay(String telephone) {
396	        if (telephone == null) {
397	            return null;
398	        }
399	        if (!telephone.matches("\\+\\d+")) {
400	            return telephone;
401	        }
402	        String digits = telephone.substring(1);
403	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
404	            if (digits.startsWith(countryCode)) {
405	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
406	            }
407	        }
408	        return "+" + groupDigits(digits);
409	    }
410	
411	    /**
412	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
413	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
414	     * {@code "412345678"} becomes {@code "412 345 678"}).
415	     *
416	     * @param digits the national digits
417	     * @return the space-grouped digits
418	     */
419	    private static String groupDigits(String digits) {
420	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
421	        for (int i = 0; i < digits.length(); i++) {
422	            if (i > 0 && i % 3 == 0) {
423	                grouped.append(' ');
424	            }
425	            grouped.append(digits.charAt(i));
426	        }
427	        return grouped.toString();
428	    }
429	
430	    /**
431	     * Required national-number length (the count of digits after the country code) for each
432	     * recognized country code, longest country code first so the prefix match is unambiguous.
433	     */
434	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
435	    static {
436	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
437	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
438	    }
439	
440	    /**
441	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
442	     * length its country code requires. A country code with no registered length places no
443	     * additional constraint and is accepted.
444	     *
445	     * @param digits the E.164 digits without the leading {@code '+'}
446	     * @return {@code true} if the national-number length is valid for the country code
447	     */
448	    private static boolean hasValidNationalNumberLength(String digits) {
449	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
450	            String countryCode = entry.getKey();
451	            if (digits.startsWith(countryCode)) {
452	                return digits.length() - countryCode.length() == entry.getValue();
453	            }
454	        }
455	        return true;
456	    }
457	
458	    /**
459	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
460	     * upper-cased abbreviation.
461	     */
462	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
463	        "ST", "STREET",
464	        "RD", "ROAD",
465	        "AVE", "AVENUE");
466	
467	    /**
468	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
469	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
470	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
471	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
472	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
473	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
474	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
475	     * value. The transform is idempotent: a normalized address normalizes to itself.
476	     *
477	     * @param address the raw address, possibly {@code null}
478	     * @return the normalized form, or {@code null} if the input was {@code null}
479	     */
480	    public static String normalizeAddress(String address) {
481	        if (address == null) {
482	            return null;
483	        }
484	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
485	        if (collapsed.isEmpty()) {
486	            return collapsed;
487	        }
488	        String[] tokens = collapsed.split(" ");
489	        StringBuilder normalized = new StringBuilder(collapsed.length());
490	        for (int i = 0; i < tokens.length; i++) {
491	            if (i > 0) {
492	                normalized.append(' ');
493	            }
494	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
495	        }
496	        return normalized.toString();
497	    }
498	
499	    /**
500	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
501	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
502	     * result is that line, with a single space and {@code addressLine2} appended when the second line
503	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
504	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
505	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
506	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
507	     *
508	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
509	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
510	     * @param flatAddress the normalized flat address, possibly {@code null}
511	     * @return the composed address, or the flat value / {@code null} when no structured line is present
512	     */
513	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
514	        if (isPresent(addressLine1)) {
515	            if (isPresent(addressLine2)) {
516	                return addressLine1 + " " + addressLine2;
517	            }
518	            return addressLine1;
519	        }
520	        return flatAddress;
521	    }
522	
523	    /**
524	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
525	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
526	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
527	     *
528	     * @param value the address field, possibly {@code null}
529	     * @return {@code true} if the value is present and non-blank
530	     */
531	    private static boolean isPresent(String value) {
532	        return value != null && !value.isBlank();
533	    }
534	
535	    /**
536	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
537	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
538	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
539	     *
540	     * @param addressLine1 the structured first line, possibly {@code null}
541	     * @param address the flat address, possibly {@code null}
542	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
543	     */
544	    public static boolean hasAddress(String addressLine1, String address) {
545	        return isPresent(addressLine1) || isPresent(address);
546	    }
547	
548	    /**
549	     * Normalize a household field (such as last name or address) to its canonical form for
550	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
551	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
552	     * that differ only in letter case or spacing are treated as the same value.
553	     *
554	     * @param value the raw field value, possibly {@code null}
555	     * @return the normalized form, or {@code null} if the input was {@code null}
556	     */
557	    public static String normalizeHousehold(String value) {
558	        if (value == null) {
559	            return null;
560	        }
561	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
562	    }
563	
564	    /**
565	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
566	     * last name (compared case-insensitively with collapsed whitespace, see
567	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
568	     * those two fields, so two owners who share a last name and postcode are assigned the same id
569	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
570	     * upper-cased hex characters of the SHA-256 digest of
571	     * {@code normalizedLastName + '|' + postcode}.
572	     *
573	     * @param lastName the owner's last name, possibly {@code null}
574	     * @param postcode the owner's postcode, possibly {@code null}
575	     * @return the household id, or {@code null} if either field is {@code null}
576	     */
577	    public static String householdId(String lastName, String postcode) {
578	        String normalizedLastName = normalizeHousehold(lastName);
579	        if (normalizedLastName == null || postcode == null) {
580	            return null;
581	        }
582	        String key = normalizedLastName + "|" + postcode;
583	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
584	    }
585	
586	    /**
587	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
588	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
589	     * so they all agree on algorithm and encoding.
590	     *
591	     * @param value the string to digest, never {@code null}
592	     * @return the 64-character lower-case hex digest
593	     */
594	    private static String sha256Hex(String value) {
595	        try {
596	            byte[] digest = MessageDigest.getInstance("SHA-256")
597	                .digest(value.getBytes(StandardCharsets.UTF_8));
598	            StringBuilder hex = new StringBuilder(digest.length * 2);
599	            for (byte b : digest) {
600	                hex.append(String.format("%02x", b));
601	            }
602	            return hex.toString();
603	        } catch (NoSuchAlgorithmException e) {
604	            // SHA-256 is a standard algorithm required to be present on every JVM.
605	            throw new IllegalStateException("SHA-256 not available", e);
606	        }
607	    }
608	
609	    /**
610	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
611	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
612	     * <ul>
613	     *   <li>{@code REGION} is the region code derived from the postcode (see
614	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
615	     *       in no known range, and</li>
616	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
617	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
618	     *       name.</li>
619	     * </ul>
620	     * The value is deterministic in the postcode, telephone and last name (e.g.
621	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
622	     *
623	     * @param postcode the owner's postcode, possibly {@code null}
624	     * @param telephone the owner's raw telephone, possibly {@code null}
625	     * @param lastName the owner's last name, possibly {@code null}
626	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
627	     */
628	    public static String customerCode(String postcode, String telephone, String lastName) {
629	        if (telephone == null || lastName == null) {
630	            return null;
631	        }
632	        String region = regionForPostcode(postcode);
633	        if (region == null) {
634	            region = "UNKNOWN";
635	        }
636	        String normalizedTelephone = normalizeTelephone(telephone);
637	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
638	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
639	    }
