641	    /**
642	     * Compute an owner's {@code identityKey}, the single derived value through which all
643	     * duplicate detection is now expressed. It consolidates the three formerly separate
644	     * telephone, email and household duplicate checks into one key, formatted as
645	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
646	     * <ul>
647	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
648	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
649	     *       when no email is present, and</li>
650	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
651	     * </ul>
652	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
653	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
654	     * members of the same household with different telephones have different keys.
655	     *
656	     * @param telephone the owner's raw telephone, possibly {@code null}
657	     * @param email the owner's email, possibly {@code null}
658	     * @param lastName the owner's last name, possibly {@code null}
659	     * @param postcode the owner's postcode, possibly {@code null}
660	     * @return the identity key, never {@code null}
661	     */
662	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
663	        String normalizedTelephone = normalizeTelephone(telephone);
664	        String normalizedEmail = normalizeEmail(email);
665	        String household = householdId(lastName, postcode);
666	        return (normalizedTelephone == null ? "" : normalizedTelephone)
667	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
668	            + "|" + (household == null ? "" : household);
669	    }
