671	    /**
672	     * The month in which the fiscal year starts (1 July). Dates on or after this month belong to
673	     * the fiscal year named for the following calendar year.
674	     */
675	    private static final int FISCAL_YEAR_START_MONTH = 7;
676	
677	    /**
678	     * Resolve the fiscal-year number for a date, where the fiscal year starts on 1 July and is
679	     * named for the calendar year in which it ends. A date in July&ndash;December belongs to the
680	     * fiscal year of the next calendar year; a date in January&ndash;June belongs to the fiscal
681	     * year of its own calendar year.
682	     *
683	     * @param date the date to resolve, never {@code null}
684	     * @return the fiscal-year number (a four-digit calendar year)
685	     */
686	    private static int fiscalYearNumber(LocalDate date) {
687	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
688	    }
689	
690	    /**
691	     * Compute an owner's {@code fiscalYear}, the fiscal year of a date formatted {@code 'FY<YY>'}
692	     * where {@code YY} is the last two digits of the fiscal-year number (see
693	     * {@link #fiscalYearNumber(LocalDate)}). The fiscal year starts on 1 July, so a date of
694	     * {@code 2026-08-01} yields {@code 'FY27'} and {@code 2026-03-01} yields {@code 'FY26'}.
695	     *
696	     * @param date the date to derive the fiscal year from, possibly {@code null}
697	     * @return the fiscal year, or {@code null} if {@code date} is {@code null}
698	     */
699	    public static String fiscalYear(LocalDate date) {
700	        if (date == null) {
701	            return null;
702	        }
703	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
704	    }
