758	    /**
759	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
760	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
761	     *
762	     * @param membershipPoints the owner's membership points
763	     * @return the membership level, an integer from 1 to 4
764	     */
765	    public static int membershipLevel(int membershipPoints) {
766	        if (membershipPoints >= 6) {
767	            return 4;
768	        }
769	        if (membershipPoints >= 4) {
770	            return 3;
771	        }
772	        if (membershipPoints >= 2) {
773	            return 2;
774	        }
775	        return 1;
776	    }
