825	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
826	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
827	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
828	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
829	     */
830	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
831	        "NSW", "Australia/Sydney",
832	        "VIC", "Australia/Melbourne",
833	        "QLD", "Australia/Brisbane");
834	
835	    /**
836	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
