895	    /**
896	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
897	     * {@code null} or empty postcode is always valid. When present it must be exactly four
898	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
899	     * range the value must fall within that inclusive range. A city with no known region accepts
900	     * any four-digit postcode. This is the single source of
901	     * truth for postcode validity, shared by the DTO validation and any persistence path.
902	     *
903	     * @param postcode the owner's postcode, possibly {@code null}
904	     * @param city the owner's city, possibly {@code null}
905	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
906	     */
907	    public static boolean isPostcodeValidForCity(String postcode, String city) {
908	        if (postcode == null || postcode.isEmpty()) {
909	            return true;
910	        }
911	        if (!postcode.matches("\\d{4}")) {
912	            return false;
913	        }
914	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
915	        if (range == null) {
916	            return true;
917	        }
918	        int value = Integer.parseInt(postcode);
919	        return value >= range[0] && value <= range[1];
920	    }
