922	    /**
923	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
924	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
925	     * value is deterministic in the customer code and is the standard Luhn check digit: each
926	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
927	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
928	     * brings the weighted sum up to the next multiple of ten.
929	     *
930	     * @param customerCode the owner's customer code, possibly {@code null}
931	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
932	     */
933	    public static Integer checkDigit(String customerCode) {
934	        if (customerCode == null) {
935	            return null;
936	        }
937	        int sum = 0;
938	        boolean dbl = true;
939	        for (int i = customerCode.length() - 1; i >= 0; i--) {
940	            char c = customerCode.charAt(i);
941	            if (c < '0' || c > '9') {
942	                continue;
943	            }
944	            int d = c - '0';
945	            if (dbl) {
946	                d *= 2;
947	                if (d > 9) {
948	                    d -= 9;
949	                }
950	            }
951	            sum += d;
952	            dbl = !dbl;
953	        }
954	        return (10 - (sum % 10)) % 10;
955	    }
