65	     */
66	    static final int MAX_OWNERS_PER_DAY = 100;
67	
68	    /**
69	     * Threshold of owners registered on a single day (counted by {@code registrationDate}) above
70	     * which a newly created owner is flagged with {@code bulkSignupWarning}. When more than this
71	     * many owners have already been created on that day, the new owner's warning is {@code true}.
72	     */
73	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
74	
75	    /** Fixed public holidays that the business-day roll skips over. */
76	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
77	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
78	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
79	        LocalDate.parse("2026-12-28"));
80	
