16	package org.springframework.samples.petclinic.service;
17	
18	import org.slf4j.Logger;
19	import org.slf4j.LoggerFactory;
20	import org.springframework.dao.DataAccessException;
21	import org.springframework.dao.EmptyResultDataAccessException;
22	import org.springframework.data.domain.Page;
23	import org.springframework.data.domain.Pageable;
24	import org.springframework.orm.ObjectRetrievalFailureException;
