29	
30	import java.time.DayOfWeek;
31	import java.time.LocalDate;
32	import java.util.Collection;
33	import java.util.List;
34	import java.util.Objects;
35	import java.util.Set;
36	import java.util.function.Supplier;
37	import java.util.stream.Collectors;
38	
39	/**
40	 * Mostly used as a facade for all Petclinic controllers
41	 * Also a placeholder for @Transactional and @Cacheable annotations
42	 *
43	 * @author Michael Isvy
44	 * @author Vitaliy Fedoriv
45	 */
46	@Service
47	public class ClinicServiceImpl implements ClinicService {
48	
49	    /**
50	     * Dedicated audit logger. Successful owner creates emit a single line here carrying the new
51	     * owner's id, customer code and registration date.
