277	    /**
278	     * Save an owner, enforcing the create-time business rules.
279	     *
280	     * <p>Because the household is keyed on {@code (lastName, postcode)} (see
281	     * {@link Owner#householdId(String, String)}), owners sharing a last name and postcode are the
282	     * same household. Duplicate rejection on create is expressed solely through the identity key:
283	     * {@link #assertIdentityIsUnique(Owner)} rejects an owner that reuses an existing normalized
284	     * telephone, and consistent with that check's contract two members of the same household with
285	     * different telephones have different identity keys and are both allowed. An undeclared household
286	     * member sharing an existing household is therefore created but flagged as a possible (suspected)
287	     * duplicate, whereas a declared household member ({@code sharesHousehold} set) is left unflagged;
288	     * {@code sharesHousehold} now governs only that flagging. This keeps the sole {@code POST /api/owners}
289	     * duplicate rule in one place and lets household members coexist, which the household
290	     * membership-level ceiling (see {@link #computeMembershipLevel(Owner)}) relies on to compare a new
291	     * owner against the existing members.
292	     */
293	    @Override
294	    @Transactional
295	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
296	        boolean isCreate = owner.isNew();
297	        assertEmailDomainAllowed(owner);
298	        assertIdentityIsUnique(owner);
299	        if (owner.isNew()) {
300	            assertCityHasCapacity(owner);
301	        }
302	        if (owner.getRegistrationDate() == null) {
303	            owner.setRegistrationDate(LocalDate.now());
304	        }
305	        assertRegistrationDateNotInFuture(owner);
306	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
307	        if (owner.isNew()) {
308	            assertDailyRegistrationLimit(owner);
309	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
310	        }
311	        if (owner.isNew() && owner.getCustomerCode() == null) {
312	            owner.setCustomerCode(generateCustomerCode(owner));
313	        }
314	        if (owner.isNew() && owner.getNamesakeCount() == null) {
315	            owner.setNamesakeCount(countNamesakes(owner));
316	        }
317	        if (owner.isNew() && owner.getHouseholdCount() == null) {
318	            owner.setHouseholdCount(countHouseholdMembers(owner));
319	        }
320	        if (owner.isNew() && owner.getMembershipLevel() == null) {
321	            owner.setMembershipLevel(computeMembershipLevel(owner));
322	        }
323	        if (owner.isNew()) {
324	            assignPossibleDuplicate(owner, sharesHousehold);
325	        }
326	        ownerRepository.save(owner);
327	        if (isCreate) {
328	            String membershipNumber = Owner.membershipNumber(owner.getCustomerCode(),
329	                owner.getRegistrationDate());
330	            int membershipLevel = owner.effectiveMembershipLevel();
331	            AUDIT.info("owner created id={} customerCode={} registrationDate={} "
332	                    + "membershipLevel={} membershipNumber={}",
333	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
334	                membershipLevel, membershipNumber);
335	        }
336	    }
337	
338	    /**
339	     * Count the existing owners that, at the moment this owner is created, share its first name
340	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
341	     * it never counts itself. This value is deterministic given the current data, so it is computed
342	     * once at creation time and stored.
343	     */
344	    private Integer countNamesakes(Owner owner) {
345	        String firstName = owner.getFirstName();
346	        String lastName = owner.getLastName();
347	        if (firstName == null || lastName == null) {
348	            return 0;
349	        }
350	        return (int) ownerRepository.findAll().stream()
351	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
352	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
353	                && lastName.equalsIgnoreCase(existing.getLastName()))
354	            .count();
355	    }
356	
357	    /**
358	     * Count the members of this owner's household at the moment it is created, i.e. the number of
359	     * owners sharing its household id (same last name and postcode, see
360	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
361	     * household id (missing last name or postcode) is counted as a single-member household. The value
362	     * is deterministic given the current data, so it is computed once at creation time and stored.
363	     */
364	    private Integer countHouseholdMembers(Owner owner) {
365	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
366	        if (householdId == null) {
367	            return 1;
368	        }
369	        long others = ownerRepository.findAll().stream()
370	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
371	            .filter(existing -> householdId.equals(
372	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
373	            .count();
374	        return (int) others + 1;
375	    }
376	
377	    /**
378	     * Compute a newly created owner's {@code membershipLevel} after applying the household level
379	     * ceiling, the value stored on the owner so every later read returns the capped level. The
380	     * owner's own uncapped level is first derived from its membership points (see
381	     * {@link Owner#membershipLevel(int)} and
382	     * {@link Owner#membershipPoints(Integer, String, Integer, java.time.LocalDate)}). The ceiling is
383	     * then one above the current maximum {@code membershipLevel} among the owner's existing household
384	     * members&mdash;other owners sharing its household id (same last name and postcode, see
385	     * {@link Owner#householdId(String, String)}), excluding soft-deleted owners and the owner itself.
386	     * Each level (the owner's own uncapped level and each member's) is read through
387	     * {@link Owner#effectiveMembershipLevel()}, the single resolver shared with the read-side mapping.
388	     * The returned level is the smaller of the uncapped level and that ceiling. When the owner has no
389	     * derivable household id or no existing household member, no ceiling applies and the uncapped
390	     * level is returned.
391	     */
392	    private Integer computeMembershipLevel(Owner owner) {
393	        int uncapped = owner.effectiveMembershipLevel();
394	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
395	        if (householdId == null) {
396	            return uncapped;
397	        }
398	        Integer maxHouseholdLevel = ownerRepository.findAll().stream()
399	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
400	            .filter(existing -> !existing.isDeleted())
401	            .filter(existing -> householdId.equals(
402	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
403	            .map(Owner::effectiveMembershipLevel)
404	            .max(Integer::compareTo)
405	            .orElse(null);
406	        if (maxHouseholdLevel == null) {
407	            return uncapped;
408	        }
409	        return Math.min(uncapped, maxHouseholdLevel + 1);
410	    }
411	
412	    /**
413	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
414	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
415	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
416	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
417	     * base value is deterministic in those fields and carries no sequence number (see
418	     * {@link Owner#customerCode(String, String, String)}).
419	     *
420	     * <p>When that computed code collides with an existing owner's {@code customerCode}, this appends
421	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
422	     * computing {@code 'NSW-1A2B3C4D'} is stored as {@code 'NSW-1A2B3C4D-2'}), so distinct owners always
423	     * receive distinct customer codes. A {@code null} computed code (missing telephone or last name) is
424	     * returned unchanged.
425	     */
426	    private String generateCustomerCode(Owner owner) {
427	        String base = Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
428	        if (base == null) {
429	            return null;
430	        }
431	        Set<String> existing = ownerRepository.findAll().stream()
432	            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
433	            .map(Owner::getCustomerCode)
434	            .filter(Objects::nonNull)
435	            .collect(Collectors.toSet());
436	        if (!existing.contains(base)) {
437	            return base;
438	        }
439	        int n = 2;
440	        while (existing.contains(base + "-" + n)) {
441	            n++;
442	        }
443	        return base + "-" + n;
444	    }
445	
446	    /**
447	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
448	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
449	     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
450	     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
451	     * existing owner that shares this owner's household id (same last name and postcode, see
452	     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
453	     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
454	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
455	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
456	     *
457	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
458	     * deliberately joins an existing household, so it is left unflagged.
459	     */
460	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
461	        if (sharesHousehold) {
462	            owner.setPossibleDuplicate(false);
463	            owner.setPossibleDuplicateOf(null);
464	            return;
465	        }
466	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
467	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
468	        Integer match = null;
469	        if (householdId != null) {
470	            match = ownerRepository.findAll().stream()
471	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
472	                .filter(existing -> !existing.isDeleted())
473	                .filter(existing -> householdId.equals(
474	                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
475	                .filter(existing -> !Objects.equals(normalizedTelephone,
476	                    Owner.normalizeTelephone(existing.getTelephone())))
477	                .map(Owner::getId)
478	                .filter(Objects::nonNull)
479	                .min(Integer::compareTo)
480	                .orElse(null);
481	        }
482	        owner.setPossibleDuplicate(match != null);
483	        owner.setPossibleDuplicateOf(match);
484	    }
485	
486	    /**
487	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
488	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
489	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
490	     * constraint.
491	     */
492	    private void assertEmailDomainAllowed(Owner owner) {
493	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
494	            throw new DisposableEmailDomainException(owner.getEmail());
495	        }
496	    }
497	
498	    /**
499	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
500	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
501	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
502	     * (normalized telephone, normalized email (or empty) and household id, see
503	     * {@link Owner#identityKey(String, String, String, String)}).
504	     *
505	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
506	     * key when their normalized telephones already match; the normalized telephone is therefore the
507	     * decisive component and is what this check compares. Consequently two members of the same
508	     * household with different telephones have different identity keys and are both allowed, while
509	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
510	     * excluded by id so updating an owner in place never conflicts with itself.
511	     */
512	    private void assertIdentityIsUnique(Owner owner) {
513	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
514	        if (normalizedTelephone == null) {
515	            return;
516	        }
517	        boolean duplicate = ownerRepository.findAll().stream()
518	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
519	            .filter(existing -> !existing.isDeleted())
520	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
521	            .anyMatch(normalizedTelephone::equals);
522	        if (duplicate) {
523	            throw new DuplicateIdentityException(Owner.identityKey(
524	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
525	        }
526	    }
527	
528	    /**
529	     * Enforce that the owner's city has not yet reached its capacity, throwing
530	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
531	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
532	     */
533	    private void assertCityHasCapacity(Owner owner) {
534	        String city = owner.getCity();
535	        if (city == null) {
536	            return;
537	        }
538	        long count = ownerRepository.findAll().stream()
539	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
540	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
541	            .count();
542	        if (count >= MAX_OWNERS_PER_CITY) {
543	            throw new CityAtCapacityException(city);
544	        }
545	    }
546	
547	    /**
548	     * Enforce that the owner's registration date is not later than the current server date, throwing
549	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
550	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
551	     * harmless no-op for that case.
552	     */
553	    private void assertRegistrationDateNotInFuture(Owner owner) {
554	        LocalDate registrationDate = owner.getRegistrationDate();
555	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
556	            throw new FutureRegistrationDateException(registrationDate);
557	        }
558	    }
559	
560	    /**
561	     * Roll a registration date forward to the next business day. A date that falls on a Saturday,
562	     * Sunday or a listed public holiday is advanced to the following non-holiday weekday; a plain
563	     * weekday is returned unchanged. This is applied to the effective registration date (whether
564	     * supplied in the request or defaulted to the server date) so that every value derived from
565	     * it&mdash;such as the membership number's year segment and the daily create-limit
566	     * counting&mdash;uses the adjusted business day.
567	     */
568	    private static LocalDate rollToBusinessDay(LocalDate date) {
569	        if (date == null) {
570	            return null;
571	        }
572	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
573	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
574	                || PUBLIC_HOLIDAYS.contains(date)) {
575	            date = date.plusDays(1);
576	        }
577	        return date;
578	    }
579	
580	    /**
581	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
582	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
583	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
584	     * is excluded by id.
585	     */
586	    private void assertDailyRegistrationLimit(Owner owner) {
587	        LocalDate registrationDate = owner.getRegistrationDate();
588	        if (registrationDate == null) {
589	            return;
590	        }
591	        long count = ownerRepository.findAll().stream()
592	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
593	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
594	            .count();
595	        if (count >= MAX_OWNERS_PER_DAY) {
596	            throw new DailyRegistrationLimitException(registrationDate);
597	        }
598	    }
599	
600	    /**
601	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
602	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
603	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
604	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
605	     * stored on the owner.
606	     */
607	    private boolean computeBulkSignupWarning(Owner owner) {
608	        LocalDate registrationDate = owner.getRegistrationDate();
609	        if (registrationDate == null) {
610	            return false;
611	        }
612	        long count = ownerRepository.findAll().stream()
613	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
614	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
615	            .count();
616	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
617	    }
