706	    /**
707	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
708	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
709	     * is the last two digits of the registration date's fiscal year (see
710	     * {@link #fiscalYear(LocalDate)}), e.g. {@code 'NSW-1A2B3C4D-M27'}. The value is deterministic
711	     * in those two fields.
712	     *
713	     * @param customerCode the owner's customer code, possibly {@code null}
714	     * @param registrationDate the owner's registration date, possibly {@code null}
715	     * @return the membership number, or {@code null} if either field is {@code null}
716	     */
717	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
718	        if (customerCode == null || registrationDate == null) {
719	            return null;
720	        }
721	        return String.format("%s-M%02d", customerCode, fiscalYearNumber(registrationDate) % 100);
722	    }
