724	    /**
725	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
726	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
727	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
728	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
729	     * of elapsed fiscal years from {@code registrationDate} to today, see
730	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
731	     * points accrue only once the owner has been a member for more than a full fiscal year.
732	     *
733	     * @param namesakeCount the owner's namesake count, possibly {@code null}
734	     * @param email the owner's email, possibly {@code null}
735	     * @param householdCount the number of members in the owner's household, possibly {@code null}
736	     * @param registrationDate the owner's registration date, possibly {@code null}
737	     * @return the membership points, a non-negative integer
738	     */
739	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
740	            LocalDate registrationDate) {
741	        int points = 0;
742	        if (email != null && !email.isEmpty()) {
743	            points += 2;
744	        }
745	        if (namesakeCount != null && namesakeCount == 0) {
746	            points += 1;
747	        }
748	        if (householdCount != null && householdCount >= 3) {
749	            points += 2;
750	        }
751	        if (registrationDate != null
752	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
753	            points += 3;
754	        }
755	        return points;
756	    }
