861	    /**
862	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
863	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
864	     * inclusive low and high bound of the region's valid 4-digit postcodes
865	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
866	     * table (including {@code 'UNKNOWN'}) places no range constraint.
867	     */
868	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
869	        "NSW", new int[] {2000, 2099},
870	        "VIC", new int[] {3000, 3099},
871	        "QLD", new int[] {4000, 4099});
