873	    /**
874	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
875	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
876	     * digits, or one that falls in no known range resolves to {@code null}.
877	     *
878	     * @param postcode the owner's postcode, possibly {@code null}
879	     * @return the matching region, or {@code null} when no range contains the postcode
880	     */
881	    private static String regionForPostcode(String postcode) {
882	        if (postcode == null || !postcode.matches("\\d{4}")) {
883	            return null;
884	        }
885	        int value = Integer.parseInt(postcode);
886	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
887	            int[] range = entry.getValue();
888	            if (value >= range[0] && value <= range[1]) {
889	                return entry.getKey();
890	            }
891	        }
892	        return null;
893	    }
