959	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
960	     * is deterministic in the email.
961	     *
962	     * @param email the owner's email, possibly {@code null}
963	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
964	     */
965	    public static String contactPreference(String email) {
966	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
967	    }
968	
969	    /**
970	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
971	     * When a title is present the result is the title and the last name separated by a single space
972	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
973	     * value is deterministic in those two fields.
974	     *
975	     * @param title the owner's honorific title, possibly {@code null} or blank
976	     * @param lastName the owner's last name, possibly {@code null}
977	     * @return the composed salutation
978	     */
979	    public static String salutation(String title, String lastName) {
980	        if (title == null || title.isBlank()) {
981	            return lastName;
982	        }
983	        return title + " " + lastName;
984	    }
985	
986	    /**
987	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
988	     * date. The age in whole years is the number of completed years between {@code birthDate} and
989	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
990	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
991	     * two fields and is only defined when both are present.
992	     *
993	     * @param birthDate the owner's date of birth, possibly {@code null}
994	     * @param registrationDate the owner's registration date, possibly {@code null}
995	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
996	     *     is {@code null}
997	     */
998	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
999	        if (birthDate == null || registrationDate == null) {
1000	            return null;
1001	        }
1002	        int age = Period.between(birthDate, registrationDate).getYears();
1003	        if (age < 18) {
1004	            return "MINOR";
1005	        }
1006	        if (age < 65) {
1007	            return "ADULT";
1008	        }
1009	        return "SENIOR";
1010	    }
