27	    /**
28	     * The owner already created for {@code key}, or {@code null} when the key is
29	     * absent/blank or has not yet produced an owner.
30	     */
31	    public Owner findCreatedOwner(String key) {
32	        if (key == null || key.isBlank()) {
33	            return null;
34	        }
35	        Integer ownerId = this.ownerIdByKey.get(key);
36	        return ownerId == null ? null : this.clinicService.findOwnerById(ownerId);
37	    }
